def call(r):
    q=urllib.parse.urlencode({"lat":r["lat"],"lon":r["lon"],"when":r["t"].replace(" ","T"),
        "ta":r["ta"],"rh":r["rh"],"wind":r["wind"],
        "cloud":(0.0 if r["expose"]=="sun" else 0.5)})
    req=urllib.request.Request("http://localhost:8000/api/v1/archive/validate?"+q,
        headers={"X-Field-Key":KEY})
    with urllib.request.urlopen(req,timeout=60) as f:
        return json.load(f)
out=[]
for i,r in enumerate(ROWS):
    try:
        res=call(r)
    except Exception as e:
        res={"ok":False,"reason":str(e)}
    if res.get("ok"):
        out.append({"place":r["place"],"t":r["t"],"lat":r["lat"],"lon":r["lon"],
            "mrt_obs":float(r["mrt_obs"]) if r["mrt_obs"] else None,
            "pet_obs":float(r["pet_obs"]) if r["pet_obs"] else None,
            "mrt_est":res["mrt"],"pvpti_est":res["pvpti"],"svf":res["svf"],
            "gvi":res["gvi"],"shade":res["shade"],"risk":res["risk"]})
    else:
        out.append({"place":r["place"],"t":r["t"],"err":res.get("reason")})
    print(f"[{i+1}/{len(ROWS)}] {r['place']} {r['t']} -> {res.get('mrt') if res.get('ok') else res.get('reason')}",file=sys.stderr)
def stats(pairs):
    if not pairs: return None
    res=[e-o for o,e in pairs]
    n=len(pairs); bias=sum(res)/n; rmse=math.sqrt(sum(d*d for d in res)/n)
    mae=sum(abs(d) for d in res)/n
    return {"n":n,"rmse":round(rmse,2),"bias":round(bias,2),"mae":round(mae,2)}
mrt=[(o["mrt_obs"],o["mrt_est"]) for o in out if o.get("mrt_est") is not None and o.get("mrt_obs") is not None]
pet=[(o["pet_obs"],o["pvpti_est"]) for o in out if o.get("pvpti_est") is not None and o.get("pet_obs") is not None]
summary={"n_total":len(ROWS),"n_ok":len([o for o in out if "mrt_est" in o]),
    "MRT":stats(mrt),"PET_vs_pVPTI":stats(pet)}
print("=====SUMMARY=====")
print(json.dumps(summary,ensure_ascii=False))
print("=====PAIRS=====")
print(json.dumps(out,ensure_ascii=False))
